tests:
test({ sr: '"true" daje true', en: '"true" gives true' }, () => {
  expect(parseBoolean('true')).toBe(true);
});
test({ sr: '"false" daje false', en: '"false" gives false' }, () => {
  expect(parseBoolean('false')).toBe(false);
});
test({ sr: 'nepoznat tekst daje null', en: 'unknown text gives null' }, () => {
  expect(parseBoolean('yes')).toBe(null);
});

hiddenTests:
test('capital letters and spaces are ignored', () => {
  expect(parseBoolean(' TRUE ')).toBe(true);
  expect(parseBoolean('False')).toBe(false);
});
test('an empty string gives null', () => {
  expect(parseBoolean('')).toBe(null);
});
test('the digit 1 is not "true"', () => {
  expect(parseBoolean('1')).toBe(null);
});

solutions.code:
function parseBoolean(text) {
  const normalized = text.trim().toLowerCase();
  if (normalized === 'true') return true;
  if (normalized === 'false') return false;
  return null;
}
